INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q633560', 'Battle of Carchemish', 'The Battle of Carchemish was a battle fought around 605 BCE between the armies of Egypt, allied with the remnants of the Neo-Assyrian Empire, against the armies of Babylonia. The forces would clash at Carchemish, an important military crossing and trade city on the banks of the Euphrates River in modern-day Syria.', -605, NULL, NULL, NULL, NULL, NULL, 'year', '605 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Carchemish'),
  ('Q389257', 'Battle of Arginusae', 'The Battle of Arginusae took place in 406 BC during the Peloponnesian War near the city of Canae in the Arginusae Islands, east of the island of Lesbos. In the battle, an Athenian fleet commanded by eight strategoi defeated a Spartan fleet under Callicratidas.', -406, 9, NULL, NULL, NULL, NULL, 'month', 'September 406 BCE', 62, 'https://en.wikipedia.org/wiki/Battle_of_Arginusae'),
  ('Q866862', 'Battle of Aegospotami', 'The Battle of Aegospotami (Greek: Μάχη στους Αιγός Ποταμούς) was a naval confrontation that took place in 405 BC and was the last major battle of the Peloponnesian War. In the battle, a Spartan fleet under Lysander destroyed the Athenian navy.', -405, NULL, NULL, NULL, NULL, NULL, 'year', '405 BCE', 67, 'https://en.wikipedia.org/wiki/Battle_of_Aegospotami'),
  ('Q192938', 'Battle of the Granicus', 'The Battle of the Granicus in May 334 BC was the first of three major battles fought between Alexander the Great of Macedon and the Persian Achaemenid Empire. The battle took place on the road from Abydus to Dascylium, at the crossing of the Granicus in the Troad region, which is now called the Biga River in Turkey.', -334, 5, NULL, NULL, NULL, NULL, 'month', 'May 334 BCE', 73, 'https://en.wikipedia.org/wiki/Battle_of_the_Granicus'),
  ('Q201526', 'Battle of Issus', 'The Battle of Issus (also Issos) occurred in southern Anatolia, on 5 November 333 BC between the Hellenic League led by Alexander the Great and the Achaemenid (or Persian) Empire, led by Darius III. It was the second major battle in Alexander''s invasion of the Persian empire, and the first encounter between Darius III and Alexander the Great. The battle resulted in the Macedonian troops defeating the Persian forces.', -333, 11, 5, NULL, NULL, NULL, 'day', '5 November 333 BCE', 76, 'https://en.wikipedia.org/wiki/Battle_of_Issus'),
  ('Q319124', 'Battle of Ipsus', 'The Battle of Ipsus (Ancient Greek: Ἱψός) was fought between the successors of Alexander the Great (referred to as the Diadochi) in 301 BC near the town of Ipsus in Phrygia. Antigonus I Monophthalmus, the Greek Macedonian ruler of large parts of Asia, and his son Demetrius were pitted against the coalition of three other successors of Alexander: Cassander, ruler of Macedon; Lysimachus, ruler of Thrace; and Seleucus I Nicator, ruler of Babylonia and Persia.', -301, NULL, NULL, NULL, NULL, NULL, 'year', '301 BCE', 69, 'https://en.wikipedia.org/wiki/Battle_of_Ipsus'),
  ('Q47299', 'Battle of Corupedium', 'The Battle of Corupedium, also called Koroupedion, Corupedion or Curupedion (Ancient Greek: Κύρου πεδίον or Κόρου πεδίον, "the plain of Kyros or Koros") was the last battle between the Diadochi, the rival successors to Alexander the Great. It was fought in 281 BC between the armies of Lysimachus and Seleucus I Nicator.', -281, NULL, NULL, NULL, NULL, NULL, 'year', '281 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Corupedium'),
  ('Q917811', 'Battle of Magnesia', 'The Battle of Magnesia took place in either December 190 or January 189 BC. It was fought as part of the Roman–Seleucid War, pitting forces of the Roman Republic led by the consul Lucius Cornelius Scipio Asiaticus and the allied Kingdom of Pergamon under Eumenes II against a Seleucid army of Antiochus III the Great. The two armies initially camped northeast of Magnesia ad Sipylum in Asia Minor (modern-day Manisa, Turkey), attempting to provoke each other into a battle on favorable terrain for several days.', -190, NULL, NULL, NULL, NULL, NULL, 'year', '190 BCE', 68, 'https://en.wikipedia.org/wiki/Battle_of_Magnesia'),
  ('Q2299845', 'Battle of Tigranocerta', 'The Battle of Tigranocerta (Armenian: Տիգրանակերտի ճակատամարտ, Tigranakerti tchakatamart) was fought on 6 October 69 BC between the forces of the Roman Republic and the army of the Kingdom of Armenia led by King Tigranes the Great. The Roman force, led by Consul Lucius Licinius Lucullus, defeated Tigranes, and as a result, captured Tigranes'' capital city of Tigranocerta.', -69, 10, 6, NULL, NULL, NULL, 'day', '6 October 69 BCE', 62, 'https://en.wikipedia.org/wiki/Battle_of_Tigranocerta'),
  ('Q205887', 'Battle of Carrhae', 'The Battle of Carrhae (Latin pronunciation: [ˈkar.rʰae̯]) was fought in 53 BC between the Roman Republic and the Parthian Empire near the ancient town of Carrhae (present-day Harran, Turkey). An invading force of seven legions of Roman heavy infantry under Marcus Licinius Crassus was lured into the desert and decisively defeated by a mixed cavalry of armoured cataphracts and light horse archers led by the Parthian general Surena.', -53, 6, 9, NULL, NULL, NULL, 'day', '9 June 53 BCE', 74, 'https://en.wikipedia.org/wiki/Battle_of_Carrhae'),
  ('Q971507', 'Battle of Zela', 'The Battle of Zela was fought in 47 BC between Julius Caesar and Pharnaces II of the Kingdom of Pontus. The battle took place near Zela (modern Zile), which is now a small hilltop town in the Tokat province of northern Turkey.', -47, 6, NULL, NULL, NULL, NULL, 'month', 'June 47 BCE', 63, 'https://en.wikipedia.org/wiki/Battle_of_Zela_(47_BC)'),
  ('Q1165502', 'Battle of Edessa', 'The Battle of Edessa took place between the armies of the Roman Empire, under the command of Emperor Valerian, and the Sasanian Empire under Shapur I, in Edessa (now the Turkish city of Urfa) in 260. The Roman army was defeated and captured in its entirety by the Sasanian forces; for the first time, a Roman emperor was taken prisoner.', 260, NULL, NULL, NULL, NULL, NULL, 'year', '260', 68, 'https://en.wikipedia.org/wiki/Battle_of_Edessa'),
  ('Q767848', 'Battle of Adrianople (324)', 'The Battle of Adrianople was fought in Thrace on July 3, 324, during a Roman civil war, the second to be waged between the two emperors Constantine I and Licinius. Licinius was soundly defeated and his army suffered heavy casualties.', 324, 7, 3, NULL, NULL, NULL, 'day', '3 July 324', 64, 'https://en.wikipedia.org/wiki/Battle_of_Adrianople_(324)'),
  ('Q192473', 'Battle of Adrianople', 'The Battle of Adrianople, also known as Battle of Hadrianopolis, was fought between the Eastern Roman army led by the Roman emperor Valens and Gothic rebels (largely Thervings as well as Greutungs, non-Gothic Alans, and various local rebels), led by Fritigern. The battle took place on 9 August 378 in the vicinity of Adrianople, in the Roman province of Thracia (modern Edirne in European Turkey).', 378, 8, 9, NULL, NULL, NULL, 'day', '9 August 378', 75, 'https://en.wikipedia.org/wiki/Battle_of_Adrianople'),
  ('Q385604', 'Battle of Dara', 'The Battle of Dara was fought between the Byzantine Empire and the Sasanian Empire in June 530 AD during the Iberian War. Following the collapse of diplomatic efforts between the Byzantine Emperor Justinian I and Shah Kavadh I, a Sasanian army advanced on the fortified city of Dara, where it was met by a smaller Byzantine force commanded by Belisarius.', 530, 6, NULL, NULL, NULL, NULL, 'month', 'June 530', 64, 'https://en.wikipedia.org/wiki/Battle_of_Dara'),
  ('Q162665', 'Nika Riots', 'The Nika riots (Greek: Στάσις τοῦ Νίκα, romanized: Stásis toû Níka), Nika revolt or Nika sedition took place against Byzantine emperor Justinian I in Constantinople over the course of a week in 532 AD. They are often regarded as the most violent riots in the city''s history, with nearly half of Constantinople being burned or destroyed and as many as thirty thousand people being killed, accounting for 5-10% of the population.', 532, 1, NULL, NULL, NULL, NULL, 'month', 'January 532', 74, 'https://en.wikipedia.org/wiki/Nika_riots'),
  ('Q312268', 'Siege of Constantinople', 'The siege of Constantinople in 626 by the Sassanid Persians and Avars, aided by large numbers of allied Slavs, ended in a strategic victory for the Byzantines. The failure of the siege saved the empire from collapse, and, combined with other victories achieved by Emperor Heraclius (r.', 626, 6, NULL, 626, 7, NULL, 'month', 'June 626 – July 626', 66, 'https://en.wikipedia.org/wiki/Siege_of_Constantinople_(626)'),
  ('Q399482', 'Siege of Constantinople', 'Constantinople was besieged by the Arabs in 674–678, in what was the first culmination of the Umayyad Caliphate''s expansionist strategy against the Byzantine Empire. Caliph Mu''awiya I, who had emerged in 661 as the ruler of the Muslim Arab empire following a civil war, renewed aggressive warfare against Byzantium after a lapse of some years and hoped to deliver a lethal blow by capturing the Byzantine capital of Constantinople.', 674, NULL, NULL, 678, NULL, NULL, 'year', '674–678', 69, 'https://en.wikipedia.org/wiki/Siege_of_Constantinople_(674%E2%80%93678)'),
  ('Q27900', 'Siege of Constantinople', 'In 717–718, Constantinople, the capital of the Byzantine Empire, was besieged by the Muslim Arabs of the Umayyad Caliphate. The campaign marked the culmination of twenty years of attacks and progressive Arab occupation of the Byzantine borderlands, while Byzantine strength was sapped by prolonged internal turmoil.', 717, 7, 15, 718, 8, 15, 'day', '15 July 717 – 15 August 718', 73, 'https://en.wikipedia.org/wiki/Siege_of_Constantinople_(717%E2%80%93718)'),
  ('Q815167', 'Siege of Constantinople', 'The siege of Constantinople in 860 was the only major military expedition of the Rus'' recorded in Byzantine and western European sources. The casus belli was the construction of the fortress Sarkel by Byzantine engineers, restricting the Rus'' trade route along the Don River in favour of the Khazars.', 860, 6, 18, 860, 8, 4, 'day', '18 June 860 – 4 August 860', 62, 'https://en.wikipedia.org/wiki/Siege_of_Constantinople_(860)'),
  ('Q200032', 'Battle of Manzikert', 'The Battle of Manzikert or Malazgirt was fought between the Byzantine Empire and the Seljuk Empire on 26 August 1071 near Manzikert, Iberia (modern Malazgirt in Muş Province, eastern Turkey). The decisive defeat of the Byzantine army and the capture of the emperor Romanos IV Diogenes played an important role in undermining Byzantine authority in Anatolia and Armenia, and allowed for the gradual Turkification of Anatolia.', 1071, 8, 26, NULL, NULL, NULL, 'day', '26 August 1071', 79, 'https://en.wikipedia.org/wiki/Battle_of_Manzikert'),
  ('Q12428', 'Battle of Dorylaeum', 'The Battle of Dorylaion or Dorylaeum took place during the First Crusade on 1 July 1097 between the crusader forces and the Seljuk Turks, near the city of Dorylaion in Anatolia. Though the Turkish forces of Kilij Arslan nearly wiped out the Crusader contingent of Bohemond of Taranto, other Crusaders arrived just in time to reverse the course of the battle.', 1097, 7, 1, NULL, NULL, NULL, 'day', '1 July 1097', 68, 'https://en.wikipedia.org/wiki/Battle_of_Dorylaeum_(1097)'),
  ('Q642117', 'Siege of Nicaea', 'The siege of Nicaea was the first major battle of the First Crusade, taking place from 14 May to 19 June 1097. The city was under the control of the Seljuk Turks who opted to surrender to the Byzantines in fear of the Crusaders breaking into the city.', 1097, 6, 19, 1097, 6, 19, 'day', '19 June 1097', 68, 'https://en.wikipedia.org/wiki/Siege_of_Nicaea'),
  ('Q741098', 'Siege of Antioch', 'The siege of Antioch took place during the First Crusade in 1097 and 1098, on the Crusaders'' way to Jerusalem through Syria. Two sieges took place in succession.', 1097, 10, 20, 1098, 6, 28, 'day', '20 October 1097 – 28 June 1098', 69, 'https://en.wikipedia.org/wiki/Siege_of_Antioch'),
  ('Q1500314', 'Battle of Harran', 'The Battle of Harran took place on 7 May 1104 between the Crusader states of the Principality of Antioch and the County of Edessa, and the Seljuk Turks. It was the first major battle against the newfound Crusader states in the aftermath of the First Crusade, marking a key turning point against Frankish expansion.', 1104, 5, 7, NULL, NULL, NULL, 'day', '7 May 1104', 65, 'https://en.wikipedia.org/wiki/Battle_of_Harran'),
  ('Q2083368', 'Siege of Edessa', 'The siege of Edessa took place from 28 November to 24 December 1144, resulting in the fall of the capital of the County of Edessa to Imad al-Din Zengi, the atabeg of Mosul and Aleppo. This event was the catalyst for the Second Crusade.', 1144, 11, 28, 1144, 12, 24, 'day', '28 November 1144 – 24 December 1144', 61, 'https://en.wikipedia.org/wiki/Siege_of_Edessa_(1144)'),
  ('Q730553', 'Battle of Myriokephalon', 'The Battle of Myriokephalon (also known as the Battle of Myriocephalum, Greek: Μάχη του Μυριοκέφαλου, Turkish: Miryokefalon Savaşı or Düzbel Muharebesi) was a battle between the Byzantine Empire and the Seljuk Turks in the mountains west of Iconium (Konya) in west-central Anatolia on 17 September 1176, during the Byzantine–Seljuk war of 1175–1179. The battle was a strategic reverse for the Byzantine forces, who were ambushed when moving through a mountain pass.', 1176, 9, 17, NULL, NULL, NULL, 'day', '17 September 1176', 66, 'https://en.wikipedia.org/wiki/Battle_of_Myriokephalon'),
  ('Q1750892', 'Siege of Constantinople', 'The sack of Constantinople occurred in April 1204 and marked the culmination of the Fourth Crusade. Crusaders sacked and destroyed most of Constantinople, the capital of the Byzantine Empire.', 1204, 4, 13, 1204, 4, 13, 'day', '13 April 1204', 69, 'https://en.wikipedia.org/wiki/Sack_of_Constantinople'),
  ('Q1427630', 'Battle of Adrianople', 'The Battle of Adrianople occurred around Adrianople on April 14, 1205, between Bulgarians, Cumans and Vlachs under the command of Tsar Kaloyan of Bulgaria, and Crusaders under Baldwin I, who only months before had been crowned Emperor of Constantinople, allied with Venetians under Doge Enrico Dandolo. The battle was won by the Bulgarian Empire after a successful ambush.', 1205, 4, 14, NULL, NULL, NULL, 'day', '14 April 1205', 62, 'https://en.wikipedia.org/wiki/Battle_of_Adrianople_(1205)'),
  ('Q1509619', 'Battle of Bapheus', 'The Battle of Bapheus occurred on 27 July 1299, between an Ottoman Turkish army under Osman I and a Byzantine army under Georgios Mouzalon. The battle ended in a crucial Ottoman victory, cementing the Ottoman state and heralding the final capture of Byzantine Bithynia by the Ottoman Turks.', 1302, 7, 27, NULL, NULL, NULL, 'day', '27 July 1302', 67, 'https://en.wikipedia.org/wiki/Battle_of_Bapheus'),
  ('Q964226', 'Battle of Pelekanon', 'The Battle of Pelekanon, also known by its Latinised form Battle of Pelecanum, occurred on June 10–11, 1329, between an expeditionary force by the Byzantines led by Andronikos IIl and an Ottoman army led by Orhan I. The Byzantine army was defeated, with no further attempt made at relieving the cities in Anatolia under Ottoman siege.', 1329, NULL, NULL, 1329, 6, 11, 'year', '1329', 61, 'https://en.wikipedia.org/wiki/Battle_of_Pelekanon'),
  ('Q209387', 'Battle of Ankara', 'The Battle of Ankara or Angora (Ottoman Turkish: آنقره محاربه‌سی, romanized: Anḳara Muḥârebesi) was fought on 28 July 1402, at the Çubuk plain near Ankara, between the forces of Timur and the Ottoman sultan Bayezid I. The battle was a major victory for Timur, leading to the Ottoman Interregnum.', 1402, 7, 20, NULL, NULL, NULL, 'day', '20 July 1402', 76, 'https://en.wikipedia.org/wiki/Battle_of_Ankara'),
  ('Q700886', 'Siege of Constantinople', 'In 1422, the Ottoman Empire laid siege to Constantinople, the capital of the Byzantine Empire, as a result of the Byzantine Emperor Manuel II''s attempts to interfere in the succession of Ottoman Sultans, after the death of Mehmed I in 1421. This policy of the Byzantines was often used successfully in weakening their neighbours.', 1422, 9, NULL, 1422, 8, NULL, 'month', 'September 1422 – August 1422', 63, 'https://en.wikipedia.org/wiki/Siege_of_Constantinople_(1422)'),
  ('Q160077', 'Fall of Constantinople', 'Constantinople, the capital city of the Byzantine Empire, was captured by the Ottoman Empire on 29 May 1453 as part of the culmination of a 53-day siege which had begun on 6 April. The attacking Ottoman Army, which significantly outnumbered Constantinople''s defenders, was commanded by Sultan Mehmed II (later titled "the Conqueror"), while the Byzantine army was led by Emperor Constantine XI Palaiologos.', 1453, 4, 6, 1453, 5, 29, 'day', '6 April 1453 – 29 May 1453', 83, 'https://en.wikipedia.org/wiki/Fall_of_Constantinople'),
  ('Q1620408', 'Battle of Chesma', 'The Battle of Chesma (also known as the Battle of Chesme, Battle of Cheshme or Battle of Cesme Bay) took place on 5–7 July 1770 in and near Çeşme, in the area between the western tip of Anatolia and the island of Chios, which was the site of a number of past naval battles between the Ottoman Empire and the Republic of Venice. It was a part of the Orlov revolt of 1770, a precursor to the later Greek War of Independence (1821–1829), and the first of a number of disastrous fleet battles for the Ottomans against Russia.', 1770, 7, 7, 1770, 7, 7, 'day', '7 July 1770', 66, 'https://en.wikipedia.org/wiki/Battle_of_Chesma'),
  ('Q427958', 'Battle of Sinop', 'The Battle of Sinop, or the Battle of Sinope, was a naval battle that took place on 30 November 1853 between Imperial Russia and the Ottoman Empire during the opening phase of the Crimean War (1853–1856). It took place at Sinop, a sea port on the southern shore of the Black Sea (the northern shore of Anatolian Turkey).', 1853, 11, 30, NULL, NULL, NULL, 'day', '30 November 1853', 67, 'https://en.wikipedia.org/wiki/Battle_of_Sinop'),
  ('Q250652', 'Battle of Sarikamish', 'The Battle of Sarikamish was an engagement between the Russian and Ottoman Empires during World War I. It took place from 22 December 1914, to 17 January 1915, as part of the Caucasus campaign. The battle resulted in a decisive Russian victory.', 1914, 12, 22, 1915, 1, 17, 'day', '22 December 1914 – 17 January 1915', 69, 'https://en.wikipedia.org/wiki/Battle_of_Sarikamish'),
  ('Q164983', 'Gallipoli Campaign', 'The Gallipoli campaign, the Dardanelles campaign, the Defence of Gallipoli or the Battle of Gallipoli (Turkish: Gelibolu Muharebesi, Çanakkale Muharebeleri or Çanakkale Savaşı) was a military campaign in the First World War on the Gallipoli Peninsula (now Gelibolu) from 19 February 1915 to 9 January 1916. The Allied powers (Britain, France and the Russian Empire) unsuccessfully attempted to make the Ottoman Empire, one of the Central Powers, capitulate by taking control of the Turkish straits.', 1915, 4, 25, 1916, 1, 9, 'day', '25 April 1915 – 9 January 1916', 82, 'https://en.wikipedia.org/wiki/Gallipoli_campaign'),
  ('Q1018969', 'Siege of Van', 'The defense of Van (Armenian: Վանի հերոսամարտ, romanized: Vani herosamart) and in Russian Van operation (Russian: Ванская операция, romanized: Vanskaya operatsia) was the armed resistance of the Armenian population of Van and Russian army against the Ottoman Empire''s attempts to massacre the Ottoman Armenian population of the Van Vilayet in the 1915 Armenian genocide. Several contemporaneous observers and later historians have concluded that the Ottoman government deliberately instigated an armed Armenian resistance in the city and then used this insurgency as the main pretext to justify…', 1915, 4, 19, 1915, 5, 17, 'day', '19 April 1915 – 17 May 1915', 64, 'https://en.wikipedia.org/wiki/Defense_of_Van_(1915)'),
  ('Q2475091', 'Operation Nemesis', 'Operation Nemesis (Armenian: «Նեմեսիս» գործողություն, romanized: "Nemesis" gortsoghut''iun) was a program of the Armenian Revolutionary Federation to assassinate both Ottoman perpetrators of the Armenian genocide and officials of the Azerbaijan Democratic Republic most responsible for the massacre of Armenians during the September Days of 1918 in Baku. Masterminded by Shahan Natalie, Armen Garo, and Aaron Sachaklian, it was named after the Greek goddess of divine retribution, Nemesis.', 1920, NULL, NULL, 1922, NULL, NULL, 'year', '1920–1922', 63, 'https://en.wikipedia.org/wiki/Operation_Nemesis'),
  ('Q234738', 'Turkish War of Independence', 'The Turkish War of Independence (15 May 1919 – 24 July 1923) was a series of military campaigns and a revolution waged by the Turkish National Movement, after the Ottoman Empire was occupied and partitioned following its defeat in World War I. The conflict was between the Turkish Nationalists and the Allied and separatist forces over the application of Wilsonian principles, especially self-determination, in post-World War I Anatolia and eastern Thrace. The revolution concluded the collapse of the Ottoman Empire and the Eastern question, ending the Ottoman sultanate and the Ottoman…', 1922, 10, 11, 1923, 7, 24, 'day', '11 October 1922 – 24 July 1923', 80, 'https://en.wikipedia.org/wiki/Turkish_War_of_Independence'),
  ('Q619712', 'Sheikh Said rebellion', 'The Sheikh Said rebellion (Kurdish: Serhildana Şêx Seîd; Turkish: Şeyh Said İsyanı) was a Kurdish nationalist and Islamist rebellion in Southeast Anatolia from February to March 1925 led by Sheikh Said and with support of the Azadî movement and local religious and feudal leaders against the newly-founded secular Republic of Turkey. The rebellion was mostly led by Zazas, but also gained support among some of the neighboring Kurmanji-speaking Kurds in the region.', 1925, 2, 13, 1925, 3, NULL, 'day', '13 February 1925 – March 1925', 61, 'https://en.wikipedia.org/wiki/Sheikh_Said_rebellion'),
  ('Q1327772', 'Dersim massacre', 'The Dersim massacre, also known as the Dersim genocide, was carried out by the Turkish military over the course of three operations in the Dersim Province (renamed Tunceli) against Kurdish rebels of Alevi faith, and civilians in 1937 and 1938. Although most Kurds in Dersim remained in their home villages, thousands were killed and many others were expelled to other parts of Turkey.', 1937, 5, 1, 1938, 9, 1, 'day', '1 May 1937 – 1 September 1938', 65, 'https://en.wikipedia.org/wiki/Dersim_massacre'),
  ('Q1859259', '1960 Turkish coup d''état', 'The 1960 Turkish coup d''état (Turkish: 27 Mayıs Darbesi), also known as the 27 May Revolution (Turkish: 27 Mayıs İhtilali or 27 Mayıs Devrimi), was the first coup d''état in the Republic of Turkey. It took place on 27 May 1960.', 1960, 5, 27, NULL, NULL, NULL, 'day', '27 May 1960', 61, 'https://en.wikipedia.org/wiki/1960_Turkish_coup_d''%C3%A9tat'),
  ('Q1758028', '1980 Turkish coup d''état', 'The 1980 Turkish coup d''état (Turkish: 12 Eylül darbesi, lit. ''12 September coup d''état''), headed by Chief of the General Staff General Kenan Evren, was the third coup d''état in the history of the Republic of Turkey, the previous having been the 1960 coup and the 1971 coup by memorandum. During the Cold War era, Turkey saw political violence (1976–1980) between the far-left, the far-right (Grey Wolves), the Islamist militant groups, and the state.', 1980, 9, 12, NULL, NULL, NULL, 'day', '12 September 1980', 65, 'https://en.wikipedia.org/wiki/1980_Turkish_coup_d''%C3%A9tat'),
  ('Q367449', '1999 İzmit earthquake', 'An earthquake of moment magnitude 7.6 struck Kocaeli Province, Turkey, on 17 August 1999. According to official figures, at least 18,373 people died and 48,901 people were injured during the earthquake, and 5,840 people were missing.', 1999, 8, 17, NULL, NULL, NULL, 'day', '17 August 1999', 69, 'https://en.wikipedia.org/wiki/1999_%C4%B0zmit_earthquake'),
  ('Q189079', 'Van earthquake of 2011', 'The 2011 Van earthquakes occurred in eastern Turkey near the city of Van. The first earthquake happened on 23 October at 13:41 local time.', 2011, 10, 23, NULL, NULL, NULL, 'day', '23 October 2011', 70, 'https://en.wikipedia.org/wiki/2011_Van_earthquakes'),
  ('Q13410316', 'Gezi Park protests', 'A wave of demonstrations and civil unrest in Turkey began on 28 May 2013, initially to contest the urban development plan for Istanbul''s Gezi Park. The protests were sparked by outrage at the violent eviction of a sit-in at the park protesting the plan.', 2013, 5, 28, NULL, NULL, NULL, 'day', '28 May 2013', 71, 'https://en.wikipedia.org/wiki/Gezi_Park_protests'),
  ('Q25007917', '2016 Istanbul airport attack', 'The Atatürk Airport attack, consisting of shootings and suicide bombings, occurred on 28 June 2016 at Atatürk Airport in Istanbul, Turkey. Gunmen armed with automatic weapons and explosive belts staged a simultaneous attack at the international terminal of Terminal 2.', 2016, 6, 28, NULL, NULL, NULL, 'day', '28 June 2016', 74, 'https://en.wikipedia.org/wiki/2016_Atat%C3%BCrk_Airport_attack'),
  ('Q28036166', 'assassination of Andrei Karlov', 'Andrei Karlov, the Russian Ambassador to Turkey, was assassinated by Mevlüt Mert Altıntaş, an off-duty Turkish police officer, at an art exhibition in Ankara, Turkey, on the evening of 19 December 2016. The assassination took place after several days of protests in Turkey over Russian involvement in the Syrian Civil War and the battle over Aleppo.', 2016, 12, 19, NULL, NULL, NULL, 'day', '19 December 2016', 71, 'https://en.wikipedia.org/wiki/Assassination_of_Andrei_Karlov'),
  ('Q28094271', '2017 Istanbul nightclub attack', 'The Istanbul nightclub shooting (also known as Reina massacre in Turkey) was a mass shooting that occurred on 1 January 2017 around 01:18 local time, in which a terrorist shot and killed 39 people and wounded 79 others at the Reina nightclub in the Ortaköy neighborhood of Istanbul, Turkey, where hundreds had been celebrating New Year''s Day. Uzbekistan-born Abdulkadir Masharipov was arrested in Istanbul on 17 January 2017.', 2017, 1, 1, NULL, NULL, NULL, 'day', '1 January 2017', 75, 'https://en.wikipedia.org/wiki/Istanbul_nightclub_shooting'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q83557758', 'Elazığ–Sivrice earthquake of 2020', 'The 2020 Elazığ earthquake occurred at 20:55 local time (17:55 UTC) on 24 January in Turkey. The magnitude of the earthquake was determined to be 6.7 Mw.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 68, 'https://en.wikipedia.org/wiki/2020_Elaz%C4%B1%C4%9F_earthquake'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q101003145', 'Aegean Sea earthquake of 2020', 'An earthquake with a moment magnitude of 7.0 occurred on 30 October 2020 about 14 km (8.7 mi) northeast of the Greek island of Samos. Although Samos was closest to the epicentre, it was the large Turkish city İzmir, 70 km (43 mi) northeast that was heavily affected—more than 700 residential and commercial structures were seriously damaged or destroyed.', 2020, 10, 30, NULL, NULL, NULL, 'day', '30 October 2020', 70, 'https://en.wikipedia.org/wiki/2020_Aegean_Sea_earthquake'),
  ('Q113295397', 'Black Sea Grain Initiative', 'The Black Sea Grain Initiative (or the Initiative on the Safe Transportation of Grain and Foodstuffs from Ukrainian ports commonly called the grain deal in the media) was an agreement between Russia, Ukraine, Turkey, and the United Nations (UN). It took place during the Russian invasion of Ukraine.', 2022, 7, 22, NULL, NULL, NULL, 'day', '22 July 2022', 62, 'https://en.wikipedia.org/wiki/Black_Sea_Grain_Initiative'),
  ('Q115193912', '2022 Istanbul bombing', 'A terrorist attack occurred on İstiklal Avenue in the Beyoğlu district of Istanbul, Turkey, on 13 November 2022 (2022-11-13), killing 6 people and injuring 81 others. No group has claimed responsibility, but Turkish authorities announced that Kurdish separatists were behind the attack, implicating the Kurdistan Workers'' Party (PKK) and the Syrian Kurdish Syrian Democratic Forces (SDF).', 2022, 11, 13, NULL, NULL, NULL, 'day', '13 November 2022', 68, 'https://en.wikipedia.org/wiki/2022_Istanbul_bombing'),
  ('Q122311648', 'Storm Daniel', 'Storm Daniel, also known as Medicane Daniel or Cyclone Daniel, was a relatively weak yet catastrophic and erratic tropical cyclone that became the deadliest Mediterranean tropical-like cyclone in recorded history, as well as the second-costliest tropical cyclone on record outside of the North Atlantic Basin (after Typhoon Doksuri). Forming as a low-pressure system around 4 September 2023, the storm affected Greece, Bulgaria, and Turkey with extensive flooding.', 2023, 9, NULL, 2023, 9, 13, 'month', 'September 2023 – 13 September 2023', 72, 'https://en.wikipedia.org/wiki/Storm_Daniel'),
  ('Q131839191', 'Grand Kartal fire', 'On 21 January 2025, a fire occurred at the Grand Kartal Hotel at the Kartalkaya ski resort in Bolu Province, Turkey; at least 78 people died, 51 others were injured. The fire started in the hotel''s fourth floor kitchen/restaurant section.', 2025, 1, 21, NULL, NULL, NULL, 'day', '21 January 2025', 63, 'https://en.wikipedia.org/wiki/2025_Kartalkaya_hotel_fire'),
  ('Q133441461', '2025 Turkish protests', 'The 2025–2026 Turkish protests are an ongoing series of demonstrations across Turkey, Northern Cyprus and the Turkish diaspora that began on 19 March 2025 following the detention and arrest of Istanbul mayor Ekrem İmamoğlu and more than 100 other opposition members, officials businessmen and protesters by Turkish authorities. İmamoğlu, at that tine member of the opposition Republican People''s Party (CHP) who had twice defeated allies of President Recep Tayyip Erdoğan in Istanbul mayoral elections, faced charges of corruption and alleged links to the Kurdish Workers'' Party (PKK); Istanbul…', 2025, 3, 19, NULL, NULL, NULL, 'day', '19 March 2025', 61, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Turkish_protests');
